mapper.select:
SELECT DETECTION_ID AS "DETECTION_ID",DETECTION_CONDITIONS AS "DETECTION_CONDITIONS" FROM enumset.cm_guoku_detection a WHERE DETECTION_TYPE_ID='04' and STATE = '0'
AND DETECTION_ID IN
#{indexId}

select *, CONCAT(z.name, '▲', z.title, '▲', z.flag) AS text from (SELECT r.INDEX_ID as id, r.INDEX_NAME as name, r.INDEX_DESCR as title, CASE WHEN r.INDEX_TYPE = '0' THEN '' WHEN r.INDEX_TYPE = '1' THEN '(%)' ELSE '' END as flag, COALESCE(r.PARENT_ID,'') as "pId", r.PARENT_ID AS "PARENT_ID", r.IDENTITY_PROPERTY AS "IDENTITY_PROPERTY" FROM indicators_lib.lib_index_relation r WHERE INDEX_STATUS='0'
AND r.PERSONAL_FLAG = #{params.personalFlag}
AND r.INDEX_ID = #{params.id}
AND r.PARENT_ID = #{params.pId}
AND r.ADD_USERID = #{params.userId}
AND r.INDEX_DIMNSN LIKE '%${params.dimensionFlag}%'
AND r.INDEX_PERIOD LIKE '%${params.periodFlag}%'
AND
r.INDEX_NAME LIKE '%${name}%'
AND
#{category} = ANY(string_to_array(COALESCE(r.CATEGORY, ''), ','))
)z
UNION ALL select *, CONCAT(b.name, '▲', b.title, '▲', b.flag) AS text from (SELECT a.INDEX_ID AS id, a.INDEX_NAME AS name, a.INDEX_DESCR AS title, CASE WHEN a.INDEX_TYPE = '0' THEN '' WHEN a.INDEX_TYPE = '1' THEN '(%)' ELSE '' END AS flag, COALESCE(a.PARENT_ID, '') AS "pId", a.PARENT_ID, a.IDENTITY_PROPERTY FROM indicators_lib.lib_index_relation a WHERE a.PARENT_ID IS NULL and a.INDEX_CORRE_TABLE is null
AND a.PERSONAL_FLAG = #{params.personalFlag}
and INDEX_STATUS='0' )b
ORDER BY PARENT_ID,IDENTITY_PROPERTY
